import{LIVESTOCK,productReady,animalStage,ANIMAL_STAGES}from'./core.js?v=48';
import{paintCute}from'./cute.js?v=9';
// Livestock stay on their tile, sway and turn now and then; a bubble shows a ready product.
const images=new Map();
async function imageFor(sprite){if(images.has(sprite))return images.get(sprite);const i=new Image();i.src=new URL(`./art/animals/${sprite}.webp`,import.meta.url).href;images.set(sprite,i);try{await i.decode();}catch{images.delete(sprite);return null;}return i;}
export const loadLivestock=()=>Promise.all(Object.values(LIVESTOCK).map(v=>imageFor(v.sprite)));
export function livestockMarkup(a,[x,y],now=Date.now()){const v=LIVESTOCK[a.kind],ready=productReady(a,now),depth=a.c+a.r+.1;return{depth,html:`<g data-node-key="animal-${a.id}" data-depth="${depth}" transform="translate(${x} ${y})"><foreignObject x="-36" y="-65" width="72" height="72" pointer-events="none"><canvas xmlns="http://www.w3.org/1999/xhtml" data-livestock="${a.id}" width="128" height="128" style="display:block;width:72px;height:72px;image-rendering:pixelated;transform-origin:50% 100%;transform:scale(${.55+.45*(animalStage(a)-1)/(ANIMAL_STAGES[a.kind]-1)})"></canvas></foreignObject>${ready?`<g class="product-bubble" transform="translate(0 -74)" pointer-events="none"><ellipse rx="27" ry="13" fill="#fffbef" stroke="#d9c6a4"/><text y="5" text-anchor="middle" font-size="12" fill="#7a6650">${v.product}</text></g>`:''}<ellipse class="object-hit" data-animal="${a.id}" cy="-26" rx="26" ry="28" role="button" tabindex="0" aria-label="${v.name} · ${animalStage(a)}/${ANIMAL_STAGES[a.kind]}단계${ready?' · '+v.product+' 받기':' · 밥 주기'}"/></g>`};}
export function paintLivestock(world,animals,time,reduced=false){for(const a of animals){const canvas=world.querySelector(`[data-livestock="${a.id}"]`),image=images.get(LIVESTOCK[a.kind]?.sprite);if(!canvas||!image?.complete)continue;const turn=Math.floor((time+a.id*7)/6)%4,row=[0,3,0,2][turn];paintCute(canvas,image,0,row,{time:time+a.id,reduced});}}
